internal enum NativeServiceStartupState
{
    Available,
    MissingWrapperOrDependency,
    JsonFallbackOnly,
}

internal static NativeServiceStartupState StartupState { get; private set; }

public MainPage()
{
    InitializeComponent();

    if (SettingsManager.IsNativeServiceAvailable)
    {
        _mappingService = new KeyboardMappingService();
    }
    else
    {
        IsNativeFallbackMode = true;
    }

    LoadAllMappings();
    UpdateBannerAndCommandState();
}

if (ShellExecuteExW(&sei) && sei.hProcess)
{
    if (WaitForSingleObject(sei.hProcess, 1000) == WAIT_OBJECT_0)
    {
        Logger::warn(L"Keyboard Manager editor exited immediately after launch; inspect WinUI3Apps dependency health.");
    }
}
